import numpy as np
from scipy.optimize import least_squares
lam=1.5406; R=240.0
obs = {'R110':(27.4353,0.003),'R200':(39.1733,0.01),'R111':(41.2344,0.006),'R211':(54.3021,0.003),
 'S111':(28.4559,0.005),'S220':(47.3185,0.005)}
a0=4.5937; c0=2.9587
def ref_tt(name,f):
    h,k,l=int(name[1]),int(name[2]),int(name[3])
    if name[0]=='R':
        inv2=(h*h+k*k)/(a0*f)**2+l*l/(c0*f)**2
        return 2*np.degrees(np.arcsin(lam*np.sqrt(inv2)/2))
    d=5.43102/np.sqrt(h*h+k*k+l*l)
    return 2*np.degrees(np.arcsin(lam/(2*d)))
names=list(obs)
tt=np.array([obs[n][0] for n in names]); sg=np.array([obs[n][1] for n in names])
def pred(p,n):
    f,z,s=p
    t=ref_tt(n,f); th=np.radians(t/2)
    return t+z+np.degrees(-2*s*np.cos(th)/R)
def resid(p): return np.array([(tt[i]-pred(p,n))/sg[i] for i,n in enumerate(names)])
for fixed in [None]:
    sol=least_squares(resid,[1.0,0.0,0.0],bounds=([0.99,-0.01,-0.2],[1.01,0.01,0.2]),x_scale=[1e-4,1e-3,0.05])
    J=sol.jac; cov=np.linalg.pinv(J.T@J)
    print('free: f=%.6f eps=%.2e +- %.2e z=%.4f s=%.3f chi2=%.1f'%(sol.x[0],sol.x[0]-1,np.sqrt(cov[0,0]),sol.x[1],sol.x[2],np.sum(sol.fun**2)))
    print(np.round(sol.fun,2))
# scan f with z,s optimized
for f in [0.9994,0.9997,1.0,1.0003,1.0006,1.0009]:
    s2=least_squares(lambda p: resid([f,p[0],p[1]]),[0,0],bounds=([-0.01,-0.2],[0.01,0.2]),x_scale=[1e-3,0.05])
    print(f, round(np.sum(s2.fun**2),2), np.round(s2.x,4))

